// Server frames are JSON text. Decode and route by type:
//   telemetry → output 1
//   heartbeat → output 2 (connection-alive ping)
//   ack       → output 3 (last command's status)
//   other     → dropped
let frame;
try { frame = JSON.parse(msg.payload); } catch (e) { return null; }
if (!frame || !frame.type) return null;

if (frame.type === 'telemetry') {
    return [{ payload: frame.data, seq: frame.seq, ts: frame.ts }, null, null];
}
if (frame.type === 'heartbeat') {
    return [null, { payload: frame.seq, ts: frame.ts }, null];
}
if (frame.type === 'ack') {
    return [null, null, { payload: frame, ref: frame.ref }];
}
return null;

// Map lp700-server's parsed telemetry frame back to the raw-byte
// shape KD4Z's `LP Dice and Slice` emitted, so any downstream nodes
// from the original flow (Peak Hold Logic, Set CH Label, Set Range
// Label, dashboard gauges, …) keep working unchanged.
//
// Server →  KD4Z key   notes
// ----------------------------------------------------------------
// power_avg_w   → power_avg   stringified watts (toFixed 0)
// power_peak_w  → power_peak  stringified watts (toFixed 0)
// swr           → swr         stringified (toFixed 2), floor 1.00
// range         → range       raw 0..11 index (5W .. 10K, 11=Auto)
// top_mode      → mode        raw 0..3 index
// channel       → channel     0=Auto, 1..4 = manual channel
// derived       → scale       full-scale watts for the active range
const RANGE_NAMES = ['5W','10W','25W','50W','100W','250W','500W','1K','2.5K','5K','10K','auto'];
const RANGE_WATTS = [5, 10, 25, 50, 100, 250, 500, 1000, 2500, 5000, 10000, 0];
const TOP_MODES   = ['power_swr', 'waveform', 'spectrum', 'setup'];

const d = msg.payload || {};
const rangeIdx = RANGE_NAMES.indexOf(d.range);
const modeIdx  = TOP_MODES.indexOf(d.top_mode);
const channelByte = d.auto_channel ? 0 : (d.channel || 0);

msg.payload = {
    power_avg:  (d.power_avg_w  || 0).toFixed(0),
    power_peak: (d.power_peak_w || 0).toFixed(0),
    swr:        (d.swr          || 1).toFixed(2),
    scale:      RANGE_WATTS[rangeIdx >= 0 ? rangeIdx : 0],
    mode:       modeIdx  >= 0 ? modeIdx  : 0,
    channel:    channelByte,
    range:      rangeIdx >= 0 ? rangeIdx : 0
};
// Keep the original parsed frame around in case a downstream node
// wants the friendlier string fields too.
msg.parsed = d;
return msg;

// Heartbeat received → set node.status to green (live).
node.status({ fill: 'green', shape: 'dot', text: 'live · seq ' + msg.payload });
return null;
